(async()=>{
 const wait=()=>new Promise(r=>setTimeout(r,200)),check=(v,m)=>{if(!v)throw Error(m)};
 const click=async(label,root=document)=>{const el=[...root.querySelectorAll('button,a')].find(el=>el.textContent.trim()===label||el.getAttribute('aria-label')===label);check(el,'Missing '+label);el.click();await wait()};
 const fill=async(label,value)=>{const input=document.querySelector(`[name="${label}"]`);check(input,'Missing '+label);Object.getOwnPropertyDescriptor(input.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(input,value);input.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 location.hash='/materials?scope=all';await wait();
 check(document.querySelector('.material-file-browser'),'Materials is not a file browser');
 await click('新建文本');await fill('标题','协作流程说明.md');await fill('正文 / 本地预览内容','# 文件流程\n只保存明确的交付依据。');await fill('操作理由 / 失败原因 / 历史使用目的','用户明确创建文件用于本地原型验证');await click('保存文件');
 check(!document.querySelector('dialog[open]'),'File create did not close');
 const state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 const file=state().resources.knowledge.find(item=>item.name==='协作流程说明.md');check(file?.library.category==='MATERIAL'&&file.library.scope==='TENANT','File went into knowledge or wrong scope');
 await click('预览');const dialog=document.querySelector('dialog[open]');check(dialog?.textContent.includes('文件流程'),'In-place file preview lost actual content');check(location.hash.split('?')[0]==='#/materials','Preview navigated away');check(dialog.getBoundingClientRect().width>=(innerWidth>=1200?Math.min(1300,innerWidth-80):innerWidth*.85),'File preview does not use available workspace width');check(decodeURIComponent(location.hash).includes('materials.preview'),'Preview not deep-linked');
 const link=dialog.querySelector('a[target="_blank"]');check(link?.getAttribute('href').includes('/materials/'+file.id),'New-tab detail targets wrong resource');
 const original=URL.createObjectURL,anchorClick=HTMLAnchorElement.prototype.click;let blob,filename;
 try{URL.createObjectURL=value=>{blob=value;return original(value)};HTMLAnchorElement.prototype.click=function(){filename=this.download};await click('下载当前文本版本',dialog);check(await blob.text()==='# 文件流程\n只保存明确的交付依据。','Downloaded different content');check(filename==='协作流程说明.md','Downloaded filename changed');}finally{URL.createObjectURL=original;HTMLAnchorElement.prototype.click=anchorClick;}
 await click('关闭弹窗',dialog);await click('图标');const card=document.querySelector('.file-card');check(card?.textContent.includes('协作流程说明.md'),'Icon mode not same files');card.click();await wait();check(document.querySelector('dialog[open]')?.textContent.includes('文件流程'),'Icon mode preview failed');await click('关闭弹窗',document.querySelector('dialog[open]'));await click('列表');
 await click('导出当前查询结果');check(document.querySelector('.resource-data-list').textContent.includes('已生成当前查询结果 JSON'),'File metadata export failed');
 check(!document.querySelector('.material-file-roots')&&!document.querySelector('.material-file-browser').textContent.includes('私人文件')&&!document.querySelector('.material-file-browser').textContent.includes('待绑定旧文件'),'Duplicate or invented file scope selector');

 await click('上传文件');const upload=document.querySelector('dialog[open] input[type=file]');check(upload,'Missing upload input');
 const transfer=new DataTransfer();transfer.items.add(new File(['actual log bytes'], 'server.log',{type:'text/plain'}));upload.files=transfer.files;upload.dispatchEvent(new Event('change',{bubbles:true}));await wait();await fill('操作理由 / 失败原因 / 历史使用目的','验证文本上传保留真实字节');await click('保存文件');
 const uploaded=state().resources.knowledge.find(item=>item.name==='server.log');check(uploaded?.library.versions[0].content==='actual log bytes','Upload replaced real bytes with metadata');check(uploaded.library.versions[0].file.textContentAvailable===true,'Upload provenance missing');
 const uploadedRow=[...document.querySelectorAll('.file-name')].find(el=>el.textContent.includes('server.log'));check(uploadedRow,'Uploaded file missing');uploadedRow.click();await wait();
 try{blob=null;filename=null;URL.createObjectURL=value=>{blob=value;return original(value)};HTMLAnchorElement.prototype.click=function(){filename=this.download};await click('下载当前文本版本',document.querySelector('dialog[open]'));check(await blob.text()==='actual log bytes'&&filename==='server.log','Uploaded text download changed bytes/name');}finally{URL.createObjectURL=original;HTMLAnchorElement.prototype.click=anchorClick;}
 await click('关闭弹窗',document.querySelector('dialog[open]'));

 await click('上传文件');const pngBytes=Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX8sAAAAASUVORK5CYII='),c=>c.charCodeAt(0)),imageTransfer=new DataTransfer();imageTransfer.items.add(new File([pngBytes],'preview.png',{type:'image/png'}));const imageInput=document.querySelector('dialog[open] input[type=file]');imageInput.files=imageTransfer.files;imageInput.dispatchEvent(new Event('change',{bubbles:true}));await wait();await fill('操作理由 / 失败原因 / 历史使用目的','验证图片原件预览');await click('保存文件');
 [...document.querySelectorAll('.file-name')].find(el=>el.textContent.includes('preview.png')).click();await wait();const image=document.querySelector('dialog[open] img');check(image?.complete&&image.naturalWidth===1,'Actual uploaded image preview missing');
 try{URL.createObjectURL=value=>{blob=value;return original(value)};HTMLAnchorElement.prototype.click=function(){filename=this.download};await click('下载原文件',document.querySelector('dialog[open]'));check(filename==='preview.png'&&JSON.stringify([...new Uint8Array(await blob.arrayBuffer())])===JSON.stringify([...pngBytes]),'Binary original download changed bytes');}finally{URL.createObjectURL=original;HTMLAnchorElement.prototype.click=anchorClick;}await click('关闭弹窗',document.querySelector('dialog[open]'));
 check(document.documentElement.scrollWidth<=innerWidth+2,'File browser overflows page');
 const headers=[...document.querySelectorAll('.material-file-main th')];check(headers.map(e=>e.textContent.replace(/[↑↕↓]/g,'').trim()).join(',')==='序号,名称,类型,大小,状态,操作','Technical columns crowd file list');check(headers.every(e=>getComputedStyle(e).whiteSpace==='nowrap'),'File headings wrap');
 if(innerWidth>=1024){const fields=[...document.querySelectorAll('.material-file-main .data-list-tools:first-of-type > .field')];check(Math.abs(fields[0].getBoundingClientRect().top-fields[1].getBoundingClientRect().top)<2,'Search/filter misaligned');}
 const refreshChoice=document.querySelector('[role=combobox][aria-label="定时刷新"]');check(refreshChoice,'Missing split refresh dropdown');refreshChoice.click();await wait();const scheduled=[...document.querySelectorAll('[role=option]')].find(e=>e.textContent==='每 30 秒刷新');check(scheduled,'Missing scheduled refresh choice');scheduled.click();await wait();const first=document.querySelector('.list-refresh-countdown')?.textContent;await new Promise(r=>setTimeout(r,1200));check(document.querySelector('.list-refresh-countdown')?.textContent!==first,'Countdown is static');await click('刷新');check(document.querySelector('.list-refresh-receipt'),'Manual refresh success missing');refreshChoice.click();await wait();[...document.querySelectorAll('[role=option]')].find(e=>e.textContent==='关闭定时刷新').click();await wait();check(!document.querySelector('.list-refresh-countdown'),'Disabled refresh retains countdown');


 await click('按名称排序，当前升序');await click('按名称排序，当前降序');await click('图标');
 check(document.querySelector('[role=combobox][aria-label="排序"]')?.textContent.includes('默认顺序'),'Icon mode mislabels the table default sort as name sorting');
 await click('列表');
 check(document.querySelector('th[aria-sort="none"] .data-list-sort')?.textContent.includes('名称'),'Table default sort was lost after icon round trip');
 return {pass:true,width:innerWidth,checks:['file manager locations','actual material creation','source/category boundary','in-place actual preview','URL selected file','new-tab canonical detail','real text download bytes/name','bounded icon mode shared files','metadata export','single shell-controlled scope','viewport fit']};
})()
